import common as C,pathlib,shutil,json,subprocess,importlib.metadata as im
A=C.ART/'A4/reproduction_002';R=C.REPORT/'A4/reproduction_002';A.mkdir(exist_ok=False);R.mkdir(exist_ok=False);C.A=A;C.R=R
release=R/'release_candidate';release.mkdir();inputs=release/'legal_inputs';scripts=release/'scripts';scripts.mkdir();paths=['reports/icde_final_gate_004/S2/resident_analysis_002/all_unprofiled_requests.csv','reports/icde_final_gate_004/S2/resident_analysis_002/static_vs_router_matched_risk.csv','reports/icde_decisive_suite_002/R2/candidate_cover_vs_quality.csv','artifacts/icde_evidence_closure_003/E2/outcomes_001/outcomes.json']
for p in paths:
 dst=inputs/p;dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(C.ROOT/p,dst)
for n in ['common.py','frontier_math.py','a1_001.py','reproduce_a1_001.py']:shutil.copyfile(pathlib.Path(__file__).parent/n,scripts/n)
for n in ['requirements_recorded.txt','environment_versions.json']:shutil.copyfile(C.REPORT/'A4/draft_002'/n,release/n)
C.prose(release/'README.md','# Private CPU reproducibility candidate\n\nThis package replays legal archived Dev measurements; it does not run new GPU retrieval or open calibration/evaluation data. No sealed B-L/test/CS/Cal/Eval payloads are included.\n\nCreate a separate environment with NumPy, SciPy and Matplotlib matching environment_versions.json. Recorded packages are an environment record, not a cross-platform universal install lock.\n\n```bash\npython scripts/reproduce_a1_001.py --input-root legal_inputs --output NEW_REPLAY_DIRECTORY\n```\n\nOutputs: matched risk/cost, offline Oracle, Probe break-even, perquery failures and figures. It checks160 historical numerical values/paired interval endpoints with tolerance1e-10. GPU traces and fresh hardware/Serving are separate, NOT reproduced by this command. Benchmark outcomes are derived from CC-BY annotation data; retain citations and source-document restrictions; no images/qrels are redistributed. Public release and rights review remain pending.\n')
C.prose(release/'LICENSES_AND_DATA.md','# Sources and licensing boundary\n\nViDoRe source metadata/cards must accompany any public release: annotations are CC-BY4.0; individual source documents retain their own rights. Current candidate contains derived legal Dev scores/costs, not page images or rawqrels. See official repositories HR/Finance-EN/Industrial/Pharmaceuticals in https://huggingface.co/vidore and their pinned revisions. Visual model is vidore/colqwen2-v1.0-merged revision2c9a09bb37ed19b63eb94ae6c29bb4e76eb6e3c2. Author code license approval is pending; this is a private candidate, not an open-source license grant. IEEEtran template retains its original notices. MMDocIR is not bundled due to unresolved metadata-vs-author licensing conflict.\n')
iv={str(p.relative_to(release)):C.sha(p) for p in release.rglob('*') if p.is_file()};C.write(release/'hash_inventory.json',iv)
out=A/'replay_output_002';log=C.ART/'logs/reproduction_002.log'
with log.open('x') as f:ret=subprocess.run([str(C.ROOT/'.venv/bin/python'),str(release/'scripts/reproduce_a1_001.py'),'--input-root',str(inputs),'--output',str(out)],stdout=f,stderr=subprocess.STDOUT,env={**__import__("os").environ,"PYTHONPATH":str(C.ROOT/"cache/report_dependencies/prereg_v2_round_001")})
assert ret.returncode==0,log
names=['matched_risk_cost_master.csv','static_frontiers.csv','oracle_gap_decomposition.csv','probe_break_even.csv','per_query_routing_diagnostics.csv','loss_attribution.csv','historical_numeric_verification.csv'];check=[]
for n in names:
 orig=C.REPORT/'A1'/n;new=out/'reports'/C.RUN/'A1'/n;check.append(dict(file=n,expected=C.sha(orig),replayed=C.sha(new),status='PASS_BYTE_IDENTICAL' if C.sha(orig)==C.sha(new) else 'FAIL'));assert check[-1]['status']=='PASS_BYTE_IDENTICAL',n
C.table(R/'replayed_table_hash_checks.csv',check);C.write(A/'complete.json',{'time_bj':C.stamp(),'status':'PASS_7_CSV_HASH_IDENTICAL','release_path':str(release),'public_release':'NOT_PUBLISHED','fresh_GPU_reproduction':'NOT_RUN'});print(json.dumps({'status':'PASS_7_CSV_HASH_IDENTICAL','time_bj':C.stamp()}),flush=True)
